// Eine Rechnung aus dem PDF-Text lesen.
// Regel wie in der Python-Fassung: eindeutig umwandeln, sonst abbrechen.
// Jede Fehlermeldung nennt die Datei, sonst sucht man sich spaeter tot.

const datei = $('Read/Write Files from Disk').item.binary?.data?.fileName ?? 'unbekannt';

function fail(msg) {
  throw new Error(`${datei}: ${msg}`);
}

function amount(text) {
  // Deutsche Schreibweise: Punkt gruppiert Tausender, Komma trennt Dezimalen.
  const cleaned = String(text).trim();
  if (!/^\d{1,3}(\.\d{3})*(,\d+)?$|^\d+(,\d+)?$/.test(cleaned)) {
    fail(`kein wohlgeformter Betrag: "${text}"`);
  }
  return parseFloat(cleaned.replace(/\./g, '').replace(',', '.'));
}

function need(re, text, field) {
  const m = text.match(re);
  if (!m) fail(`${field} nicht gefunden - Layout hat sich vermutlich geaendert`);
  return m[1].trim();
}

const text = $json.text;

// Ein Adapter pro Layout. Unbekanntes Dokument wird abgelehnt, nicht geraten.
if (!/MUSTERFIRMA/i.test(text)) {
  fail('unbekanntes Layout - kein Adapter fuer diesen Lieferanten');
}

const number   = need(/Rechnung Nr\.\s*(\S+)/, text, 'Rechnungsnummer');
const dateText = need(/Rechnungsdatum:\s*(\S+)/, text, 'Rechnungsdatum');
const customer = need(/Kunde:\s*(.+)/, text, 'Kunde');

// Datum nur im ausdruecklich erwarteten Format - nicht raten lassen.
const dm = dateText.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
if (!dm) fail(`Datum "${dateText}" ist nicht tt.mm.jjjj`);
const date = `${dm[3]}-${dm[2]}-${dm[1]}`;

let net = null, vat = null, gross = null;
const items = [];

for (const raw of text.split('\n')) {
  const line = raw.trim();
  if (!line || line.startsWith('Position ')) continue;

  let m;
  if ((m = line.match(/^Gesamtbetrag netto\s+([\d.,]+)$/))) { net = amount(m[1]); continue; }
  if ((m = line.match(/^zzgl\..*?\s+([\d.,]+)$/)))          { vat = amount(m[1]); continue; }
  if ((m = line.match(/^Rechnungsbetrag\s+([\d.,]+)$/)))    { gross = amount(m[1]); continue; }

  if ((m = line.match(/^(.+?)\s+(\d+)\s+([\d.,]+)\s+([\d.,]+)$/))) {
    items.push({
      beschreibung: m[1].trim(),
      menge: parseInt(m[2], 10),
      einzelpreis: amount(m[3]),
      summe: amount(m[4]),
    });
  }
}

for (const [value, label] of [[net, 'Nettosumme'], [vat, 'MwSt'], [gross, 'Bruttosumme']]) {
  if (value === null) fail(`${label} fehlt in Rechnung ${number}`);
}

// Gegenprobe: Positionen muessen die Nettosumme ergeben.
const sum = Math.round(items.reduce((a, i) => a + i.summe, 0) * 100) / 100;

return {
  json: {
    datei,
    rechnungsnummer: number,
    datum: date,
    kunde: customer,
    netto: net,
    mwst: vat,
    brutto: gross,
    positionen: items.length,
    positionssumme: sum,
    stimmig: Math.abs(sum - net) < 0.01,
    items,
  },
};

// Aus jeder Rechnung wird je Position eine eigene Zeile.
// Rechnungsnummer, Datum und Kunde wandern mit, damit jede Zeile
// fuer sich lesbar ist und man sie spaeter zuordnen kann.
const zeilen = [];

for (const entry of $input.all()) {
  const r = entry.json;
  for (const pos of r.items ?? []) {
    zeilen.push({
      json: {
        rechnungsnummer: r.rechnungsnummer,
        datum: r.datum,
        kunde: r.kunde,
        beschreibung: pos.beschreibung,
        menge: pos.menge,
        einzelpreis: pos.einzelpreis,
        summe: pos.summe,
      },
    });
  }
}

if (zeilen.length === 0) {
  throw new Error('keine Positionen gefunden - kamen die Rechnungen ohne Einzelposten?');
}

return zeilen;

// Eine Zeile je Rechnung, ohne die verschachtelten Positionen.
// Modus "All Items": wir bekommen den ganzen Stapel und geben eine Liste zurueck.
return $input.all().map(entry => {
  const { items, ...kopf } = entry.json;
  return { json: kopf };
});

// Den Dateinamen direkt beim Lese-Knoten holen, nicht aus der Meldung parsen.
// n8n kann den zugehoerigen Eintrag nur im Each-Item-Modus zuordnen.
let datei = 'unbekannt';
try {
  datei = $('Read/Write Files from Disk').item.binary?.data?.fileName ?? 'unbekannt';
} catch (e) {
  // Zuordnung nicht aufloesbar - dann bleibt es bei "unbekannt"
}

const roh = $json.error;
let problem = typeof roh === 'string' ? roh : (roh?.message ?? JSON.stringify(roh));

// n8n haengt eine interne Zeilennummer an - fuer eine Pruefliste unbrauchbar.
problem = problem.replace(/\s*\[line \d+\]\s*$/, '');

// Falls die Meldung den Dateinamen doch mitbringt, nicht doppelt schreiben.
if (problem.startsWith(datei + ': ')) {
  problem = problem.slice(datei.length + 2);
}

return {
  json: {
    datei,
    problem,
    zeitpunkt: new Date().toISOString(),
  },
};

// Zeitstempel ohne Luxon: im Task-Runner von n8n 2.x ist $now kein
// DateTime-Objekt mehr, $now.format() gibt es dort nicht.
// Die Zeitzone muss ausdruecklich mit - der Task-Runner laeuft in UTC,
// auch wenn der Container auf Europe/Berlin steht.
function stempelJetzt(mitSekunden) {
  // 'sv-SE' liefert 2026-09-11 11:48:53, also schon fast ISO.
  const s = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' });
  return mitSekunden ? s : s.slice(0, 10) + '_' + s.slice(11, 16).replace(':', '-');
}

// Verarbeitete Dokumente wegraeumen.
// Erst jetzt, nachdem beide Mappen geschrieben sind - bricht vorher etwas
// ab, bleiben die PDFs liegen und der naechste Lauf holt sie erneut.
//
// Kein Execute-Command-Knoten: den gibt es im offiziellen n8n-Image nicht
// mehr. Stattdessen fs direkt, dafuer braucht der Container
// NODE_FUNCTION_ALLOW_BUILTIN=fs.
const fs = require('fs');

const stempel = stempelJetzt(false);
const gesehen = new Set();
const ergebnis = [];

for (const eintrag of $('Nur Kopfdaten').all()) {
  const datei = eintrag.json.datei;
  if (!datei || datei === 'unbekannt' || gesehen.has(datei)) continue;
  gesehen.add(datei);

  const von = `/data/pdfs/${datei}`;
  const nach = `/data/_beiseite/${stempel}_${datei}`;

  try {
    fs.renameSync(von, nach);
    ergebnis.push({ json: { datei, ziel: nach, verschoben: true, art: 'gelesen' } });
  } catch (e) {
    // Nicht den ganzen Lauf abbrechen - die Mappen sind schon geschrieben.
    ergebnis.push({ json: { datei, verschoben: false, fehler: e.message, art: 'gelesen' } });
  }
}

// Nie leer zurueckgeben, sonst laeuft der Protokollzweig dahinter nicht an.
if (ergebnis.length === 0) {
  return [{ json: { datei: null, verschoben: false, hinweis: 'nichts zu verschieben', art: 'gelesen' } }];
}

return ergebnis;

// Zeitstempel ohne Luxon: im Task-Runner von n8n 2.x ist $now kein
// DateTime-Objekt mehr, $now.format() gibt es dort nicht.
// Die Zeitzone muss ausdruecklich mit - der Task-Runner laeuft in UTC,
// auch wenn der Container auf Europe/Berlin steht.
function stempelJetzt(mitSekunden) {
  // 'sv-SE' liefert 2026-09-11 11:48:53, also schon fast ISO.
  const s = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' });
  return mitSekunden ? s : s.slice(0, 10) + '_' + s.slice(11, 16).replace(':', '-');
}

// Verarbeitete Dokumente wegraeumen.
// Erst jetzt, nachdem beide Mappen geschrieben sind - bricht vorher etwas
// ab, bleiben die PDFs liegen und der naechste Lauf holt sie erneut.
//
// Kein Execute-Command-Knoten: den gibt es im offiziellen n8n-Image nicht
// mehr. Stattdessen fs direkt, dafuer braucht der Container
// NODE_FUNCTION_ALLOW_BUILTIN=fs.
const fs = require('fs');

const stempel = stempelJetzt(false);
const gesehen = new Set();
const ergebnis = [];

for (const eintrag of $('Problemfälle sammeln').all()) {
  const datei = eintrag.json.datei;
  if (!datei || datei === 'unbekannt' || gesehen.has(datei)) continue;
  gesehen.add(datei);

  const von = `/data/pdfs/${datei}`;
  const nach = `/data/pruefen/${stempel}_${datei}`;

  try {
    fs.renameSync(von, nach);
    ergebnis.push({ json: { datei, ziel: nach, verschoben: true, art: 'fehlerhaft' } });
  } catch (e) {
    // Nicht den ganzen Lauf abbrechen - die Mappen sind schon geschrieben.
    ergebnis.push({ json: { datei, verschoben: false, fehler: e.message, art: 'fehlerhaft' } });
  }
}

// Nie leer zurueckgeben, sonst laeuft der Protokollzweig dahinter nicht an.
if (ergebnis.length === 0) {
  return [{ json: { datei: null, verschoben: false, hinweis: 'nichts zu verschieben', art: 'fehlerhaft' } }];
}

return ergebnis;

// Zeitstempel ohne Luxon: im Task-Runner von n8n 2.x ist $now kein
// DateTime-Objekt mehr, $now.format() gibt es dort nicht.
// Die Zeitzone muss ausdruecklich mit - der Task-Runner laeuft in UTC,
// auch wenn der Container auf Europe/Berlin steht.
function stempelJetzt(mitSekunden) {
  // 'sv-SE' liefert 2026-09-11 11:48:53, also schon fast ISO.
  const s = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' });
  return mitSekunden ? s : s.slice(0, 10) + '_' + s.slice(11, 16).replace(':', '-');
}

// Eine Zeile je Lauf, angehaengt an /data/ausgabe/protokoll.txt.
// Die Zahlen kommen von den Quellknoten, nicht aus dem Merge-Eingang -
// so stimmt die Zaehlung auch, wenn ein Zweig gar nicht gelaufen ist.
const zeitpunkt = stempelJetzt(true);

function eintraege(knoten) {
  try {
    return $(knoten).all().filter(e => e.json && Object.keys(e.json).length > 0);
  } catch (e) {
    return [];   // Zweig ist in diesem Lauf nicht angelaufen
  }
}

const gelesen = eintraege('Nur Kopfdaten');
const fehler  = eintraege('Problemf\u00e4lle sammeln');

const summe = gelesen.reduce((a, e) => a + (e.json.brutto ?? 0), 0);
const unstimmig = gelesen.filter(e => e.json.stimmig === false).map(e => e.json.datei);

let zeile = `${zeitpunkt} | ${gelesen.length} gelesen | ${fehler.length} fehlerhaft`;
zeile += ` | brutto ${summe.toFixed(2)}`;

if (unstimmig.length) {
  zeile += ` | Positionssumme weicht ab: ${unstimmig.join(', ')}`;
}
for (const e of fehler) {
  zeile += `\n    ! ${e.json.datei}: ${e.json.problem}`;
}

const text = zeile + '\n';
const binaer = await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'),
                                                   'protokoll.txt', 'text/plain');

return [{
  json: { zeitpunkt, gelesen: gelesen.length, fehlerhaft: fehler.length },
  binary: { data: binaer },
}];
